import { Component, Element, Host, Prop, h } from "@stencil/core";
import { addConstructedStyle } from "../../utils/browser";

/**
 * @since 2.12.0
 * @status stable
 *
 * @slot - The text for truncation
 *
 */

@Component({
  tag: "hbr-truncation",
  styleUrl: "truncation.scss",
  shadow: true,
})
export class Truncation {
  private sheet: CSSStyleSheet = new CSSStyleSheet();
  @Element() host: HTMLHbrTruncationElement;
  ref: HTMLSpanElement;
  private truncated = false;

  /** Allow limiting of the contents of a block to the specified number of lines.  */
  @Prop({ reflect: true }) lines = 1;

  /** The target element for the tooltip. This can be a string or an hbr-tooltip reference. */
  @Prop() tooltipTarget: string | HTMLHbrTooltipElement;

  getTooltipTarget = () => {
    if (typeof this.tooltipTarget === "string") {
      return document.body.querySelector(
        this.tooltipTarget
      ) as HTMLHbrTooltipElement;
    }
    if (this.tooltipTarget instanceof HTMLElement) {
      return this.tooltipTarget as HTMLHbrTooltipElement;
    }
  };

  handleHideTooltip = (event) => {
    event.currentTarget?.setAttribute("data-truncation-hidden", "true");
    event.currentTarget?.removeEventListener(
      "hbr-popup-hide",
      this.handleHideTooltip
    );
  };

  handleMouseEnter = () => {
    const tooltip = this.getTooltipTarget();
    if (!tooltip) return;
    if (tooltip.tagName !== "HBR-TOOLTIP") {
      console.warn(
        "hbr-truncation: The tooltipTarget only supports hbr-tooltip"
      );
    }
    this.clearTooltipSelection(tooltip);
    if (this.isTruncated()) {
      tooltip.addEventListener("hbr-popup-hide", this.handleHideTooltip);
      tooltip.onmousedown = (e) => {
        e.stopPropagation();
      };
      tooltip.onmouseup = (e) => {
        e.stopPropagation();
      };
      tooltip.anchor = this.host;
      tooltip.open = true;
      tooltip.content = this.host.textContent;
      tooltip.removeAttribute("data-truncation-hidden");
    } else {
      tooltip.anchor = undefined;
      tooltip.open = false;
      tooltip.content = "";
      tooltip.setAttribute("data-truncation-hidden", "true");
    }
  };

  private isTruncated = () => {
    this.truncated =
      this.host.scrollHeight > this.host.clientHeight ||
      this.host.scrollWidth > this.host.clientWidth ||
      this.ref?.scrollHeight > this.ref?.clientHeight ||
      this.ref?.scrollWidth > this.ref?.clientWidth;
    if (this.truncated) {
      this.host.setAttribute("data-truncated", "true");
    } else {
      this.host.removeAttribute("data-truncated");
    }
    return this.truncated;
  };

  componentDidLoad() {
    this.isTruncated();
  }

  private nodeIsInTooltip = (
    node: Node | null,
    tooltip: HTMLHbrTooltipElement
  ): boolean => {
    return (
      !!node &&
      (node === tooltip ||
        tooltip.contains(node) ||
        !!tooltip.shadowRoot?.contains(node))
    );
  };

  private selectionIsInTooltip = (
    selection: Selection,
    tooltip: HTMLHbrTooltipElement
  ): boolean => {
    return (
      !selection.isCollapsed &&
      (this.nodeIsInTooltip(selection.anchorNode, tooltip) ||
        this.nodeIsInTooltip(selection.focusNode, tooltip))
    );
  };

  private clearTooltipSelection = (tooltip: HTMLHbrTooltipElement) => {
    const selection = window.getSelection();

    if (selection && tooltip && this.selectionIsInTooltip(selection, tooltip)) {
      selection.removeAllRanges();
    }
  };

  handleMouseLeave = () => {
    const tooltip = this.getTooltipTarget();

    if (tooltip) {
      this.clearTooltipSelection(tooltip);
    }
  };

  render() {
    const { lines } = this;
    if (this.host) {
      this.sheet.replaceSync(`
    		:host {
					--line-clamp: ${lines};
    		}
    	`);
      addConstructedStyle(this.host.shadowRoot, this.sheet);
    }

    return (
      <Host
        onMouseOver={this.handleMouseEnter}
        onMouseLeave={this.handleMouseLeave}
      >
        <span
          ref={(el) => {
            this.ref = el;
            this.isTruncated();
          }}
          class={{
            truncation: true,
            "truncation--multi": this.lines > 1,
          }}
        >
          <slot onSlotchange={this.isTruncated} />
        </span>
      </Host>
    );
  }
}
